window.AUTH=window.AUTH||{};window.AUTH["19-199"]={"d":"19-199","id":"2020/19-199","n":"Salinas v. United States Railroad Retirement Board","briefs":[{"k":"petitioner","label":"Brief of petitioner Manfredo Salinas","date":"2020-03-31","url":"https://www.supremecourt.gov/DocketPDF/19/19-199/139527/20200331124815574_Salinas%20Merits%20Brief%20-%203.30%20FINAL.pdf","side":"pet","n":49},{"k":"respondent","label":"Brief of respondent United States Railroad Retirement Board","date":"2020-06-08","url":"https://www.supremecourt.gov/DocketPDF/19/19-199/145162/20200608161534224_19-199bsUnitedStates.pdf","side":"res","n":77},{"k":"reply","label":"Reply of petitioner Manfredo Salinas","date":"2020-07-08","url":"https://www.supremecourt.gov/DocketPDF/19/19-199/147205/20200708114850218_19-199%20-%20Salinas%20v.%20RRB%20-%20Reply.pdf","side":"pet","n":34}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/19-199_o7jq.pdf","tr":true,"items":[{"t":"case","label":"Abbott Labs. v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"[t]he right to review is too important to be excluded on such slender and indeterminate evidence.","cite":"387 U.S. 136, 141"}]},{"t":"case","label":"Abbruzzese v. R.R. Ret. Bd.","cite":"63 F.3d 972","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/63/972/","by":{"0":"40","1":"48"}},{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"[R]ead naturally, the word ‘any’ has an expansive meaning, that is, ‘one or some indiscriminately of whatever kind.’","cite":"552 U.S. 214, 219"}]},{"t":"case","label":"Alton R.R. Co. v. R.R. Ret. Bd.","cite":"16 F. Supp. 955","y":1936,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./16/955/","by":{"0":"5"}},{"t":"case","label":"Barnhart v. Thomas","cite":"540 U.S. 20","y":2003,"id":"2003/02-763","sc":1,"by":{"0":"31","2":"13"},"q":[{"src":"brief","b":0,"text":"‘a limiting clause or phrase … should ordinarily be read as modifying only the noun or phrase that it immediately follows.’","cite":"540 U.S. 20, 26"},{"src":"brief","b":2,"text":"it is precisely contrary to … the grammatical ‘rule of the last antecedent.’","cite":"540 U.S. 20, 26"}]},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"by":{"0":"23","1":"33"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"both (1) mark[s] the consummation of the agency’s decisionmaking process and (2) is one by which rights or obligations have been determined, or from which legal consequences will flow.","cite":"520 U. S. 154, 177–178"}]},{"t":"case","label":"BNSF Ry. Co. v. Loos","cite":"139 S. Ct. 893","y":2019,"id":"2018/17-1042","sc":1,"by":{"0":"6","1":"20"},"q":[{"src":"brief","b":0,"text":"provides generous pensions as well as benefits ‘correspon[ding] ... to those an employee would expect to receive were he covered by the Social Security Act.’","cite":"139 S. Ct. 893, 897"}]},{"t":"case","label":"Bowen v. Mich. Acad. of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"by":{"0":"24, 25, 39, 41","1":"41, 42"},"q":[{"src":"brief","b":1,"text":"has never applied the clear and convincing evidence standard in the strict evidentiary sense.","cite":"476 U.S. at 672 n.3"}]},{"t":"case","label":"Burke v. R.R. Ret. Bd.","cite":"165 F.2d 24","y":1947,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/165/24/","by":{"0":"37"}},{"t":"case","label":"Califano v. Sanders","cite":"430 U.S. 99","y":1977,"id":"1976/75-1443","sc":1,"by":{"0":"passim","1":"passim","2":"4, 8, 11, 20"},"q":[{"src":"brief","b":1,"text":"seeks only an additional opportunity to establish that he satisfies the [RRA’s] eligibility standards for disability benefits.","cite":"430 U.S. at 109"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"the adjudication of colorable constitutional claims.","cite":"430 U. S. 99, 109"},{"src":"argument","who":"Justice Breyer","text":"It's both Your Home Visiting Nurse and also Califano v. Sanders. Then you have the fact that nobody -- no lower court decided in your favor, I think -- maybe there was an exception, I don't know -- since the 1960s or 1970s, and since then, the cases have gone the other way in the lower courts, and it would make a kind of hash of the statute of limitations."},{"src":"argument","who":"Ms. Harris","text":"I'd like to take Your Home and Califano first, because I think that Your Home, when it said that there is a sort of -- that reopening seemed like a refusal --"},{"src":"argument","who":"Ms. Harris","text":"And if you took Your Home to be foreclosing judicial review of all sorts of reopening claims based on new evidence, that would be a sea change in the way the Court has considered them. Now Califano --"}]},{"t":"case","label":"Cunningham v. R.R. Ret. Bd.","cite":"392 F.3d 567","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/392/567/","by":{"0":"30, 40, 43","1":"48"}},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"136 S. Ct. 2131","y":2016,"id":"2015/15-446","sc":1,"by":{"0":"25","1":"42"},"q":[{"src":"brief","b":0,"text":"‘The determination … whether to institute an inter partes review under this section shall be final and non-appealable.’","cite":"136 S. Ct. at 2136"}]},{"t":"case","label":"Denberg v. R.R. Ret. Bd.","cite":"696 F.2d 1193","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/696/1193/","by":{"0":"9, 38"}},{"t":"case","label":"Dep’t of Homeland Sec. v. MacLean","cite":"135 S. Ct. 913","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/913/","sc":1,"by":{"0":"20"}},{"t":"case","label":"Free Enter. Fund v. Pub. Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"by":{"0":"40"}},{"t":"case","label":"Gundy v. United States","cite":"139 S. Ct. 2116","y":2019,"id":"2018/17-6086","sc":1,"by":{"0":"43"}},{"t":"case","label":"Harris v. R.R. Ret. Bd.","cite":"198 F.3d 139","y":1999,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/198/139/","by":{"0":"30, 40","1":"48"}},{"t":"case","label":"Hisquierdo v. Hisquierdo","cite":"439 U.S. 572","y":1979,"id":"1978/77-533","sc":1,"by":{"0":"6"}},{"t":"case","label":"Intel Corp. Inv. Policy Comm. v. Sulyma","cite":"140 S. Ct. 768","y":2020,"id":"2019/18-1116","sc":1,"by":{"0":"18"}},{"t":"case","label":"Johnson v. R.R. Ret. Bd.","cite":"925 F.2d 1374","y":1991,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/925/1374/","by":{"0":"36"}},{"t":"case","label":"King v. R.R. Ret. Bd.","cite":"981 F.2d 365","y":1992,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/981/365/","by":{"0":"37"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"by":{"0":"24","1":"37","2":"8, 20, 21, 23"},"q":[{"src":"brief","b":1,"text":"[f ]ederal-court review of administrative decisions denying motions to reopen removal proceedings dates back to at least 1916.","cite":"558 U.S. 233, 240 n.5"},{"src":"argument","who":"Ms. Harris","text":"But, as I think the Court noted in Kucana versus Holder, the word \"under\" is a bit of a chameleon and it depends on context. And it would be strange to think that the RRA only means under the statute and not under the different regulations that the Board might promulgate when we have a statute here where Congress was pretty clear that it was delegating to the Board a lot of power to make --"},{"src":"argument","who":"Ms. Harris","text":"Because, if you thought of it that way, I think you'd have to override a really long tradition of judicial review in cases like Kucana versus Holder and Brotherhood of Locomotive Engineers that holds the contrary and says denials of reopening that are based on new evidence are judicially reviewable because they're final agency actions."}]},{"t":"case","label":"Lindahl v. Office of Pers. Mgmt.","cite":"470 U.S. 768","y":1985,"id":"1984/83-5954","sc":1,"by":{"0":"25"}},{"t":"case","label":"Lockhart v. United States","cite":"136 S. Ct. 958","y":2016,"id":"2015/14-8358","sc":1,"by":{"0":"31, 32","1":"24, 25"},"q":[{"src":"brief","b":0,"text":"list … terms or phrases followed by a limiting clause.","cite":"136 S. Ct. 958, 962"},{"src":"brief","b":1,"text":"‘a limiting clause or phrase should ordinarily be read as modifying only the noun or phrase that it immediately follows.’","cite":"136 S. Ct. 958, 962-963"},{"src":"brief","b":1,"text":"can assuredly be overcome by other indicia of meaning.","cite":"136 S. Ct. at 963"}]},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"575 U.S. 489","y":2015,"url":"https://supreme.justia.com/cases/federal/us/575/489/","sc":1,"by":{"0":"24, 25, 41"},"q":[{"src":"brief","b":0,"text":"[L]egal lapses and violations occur, and especially so when they have no consequence. That is why this Court has so long applied a strong presumption favoring judicial review of administrative action.","cite":"575 U.S. 489, 486"}]},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"0":"33"}},{"t":"case","label":"Myers v. United States","cite":"272 U.S. 602","y":1926,"id":"1900-1940/272us52","sc":1,"by":{"0":"39"}},{"t":"case","label":"Pub. Citizen v. U.S. Dep’t of Justice","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"by":{"0":"39"}},{"t":"case","label":"R.R. Ret. Bd. v. Alton R. Co.","cite":"295 U.S. 330","y":1935,"id":"scdb/1934-051","sc":1,"by":{"0":"5"}},{"t":"case","label":"Regions Hosp. v. Shalala","cite":"522 U.S. 448","y":1998,"id":"1997/96-1375","sc":1,"by":{"0":"28"}},{"t":"case","label":"Roberts v. U.S. R.R. Ret. Bd.","cite":"346 F.3d 139","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/346/139/","by":{"0":"14, 30, 40, 43","1":"11, 12, 48"},"q":[{"src":"brief","b":0,"text":"final decisions on the merits of a claim as described in [45 U.S.C.] 355(c)","cite":"346 F.3d 139, 141"}]},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"by":{"0":"18"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"0":"20"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"Where Congress includes particular language in one section of a statute but omits it in another section of the same Act, it is generally presumed that Congress acts intentionally and purposely in the disparate inclusion or exclusion.","cite":"464 U. S. 16, 23"}]},{"t":"case","label":"Salinas v. U.S. R.R. Ret. Bd.","cite":"765 F. App’x 79","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/765/79/","by":{"0":"1"}},{"t":"case","label":"Scott v. R.R. Ret. Bd.","cite":"631 F.3d 359","y":2011,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/631/359/","by":{"0":"37"}},{"t":"case","label":"Smith v. Berryhill","cite":"139 S. Ct. 1765","y":2019,"id":"2018/17-1606","sc":1,"by":{"0":"passim","1":"30, 36, 38","2":"3, 4, 8"},"q":[{"src":"brief","b":0,"text":"a massive enterprise, and mistakes will occur.","cite":"139 S. Ct. at 1776"},{"src":"brief","b":0,"text":"judicial review of ‘any final decision of the [agency] made after a hearing.’","cite":"139 S. Ct. at 1771"},{"src":"argument","who":"Ms. Harris","text":"And in Smith versus Berryhill, the Court emphasized that while reopening could be a final decision, it certainly wasn't one made after a hearing in that context."}]},{"t":"case","label":"Steebe v. R.R. Ret. Bd.","cite":"708 F.2d 250","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/708/250/","by":{"0":"9, 30, 38, 40","1":"48"}},{"t":"case","label":"Stovic v. R.R. Ret. Bd.","cite":"826 F.3d 500","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/826/500/","by":{"0":"passim","1":"48","2":"9, 10, 11, 12"},"q":[{"src":"brief","b":0,"text":"any final decision of the Board","cite":"826 F.3d 500, 503"},{"src":"brief","b":0,"text":"It makes sense to provide for judicial review of potentially arbitrary and mistaken Board decisions denying requests to reopen. Judicial review helps ensure accuracy and fairness.","cite":"826 F.3d at 505"}]},{"t":"case","label":"Szostak v. R.R. Ret. Bd.","cite":"370 F.2d 253","y":1966,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/370/253/","by":{"0":"9","1":"48"}},{"t":"case","label":"U.S. Army Corps of Eng’rs v. Hawkes Co.","cite":"136 S. Ct. 1807","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1807/","sc":1,"by":{"0":"passim","2":"3, 22"},"q":[{"src":"brief","b":0,"text":"by which rights or obligations have been determined, or from which legal consequences will flow.","cite":"136 S. Ct. at 1813"}]},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"by":{"0":"19"}},{"t":"reg","label":"20 C.F.R. § 210.7","url":"https://www.ecfr.gov/current/title-20/section-210.7","by":{"0":"36"}},{"t":"reg","label":"60 Fed. Reg. 66,203","url":"https://www.govinfo.gov/link/fr/60/66203","by":{"0":"9","2":"23"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(1)(E)"],"by":{"0":"29, 38"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"35 U.S.C. § 314","url":"https://www.law.cornell.edu/uscode/text/35/314","subs":["(d)"],"by":{"0":"25"}},{"t":"usc","label":"42 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/42/405","subs":["(g)","(g)(1976)"],"stext":{"head":"§405. Evidence, procedure, and certification for payments","paras":[[0,"(a) Rules and regulations; procedures"],[0,"The Commissioner of Social Security shall have full power and authority to make rules and regulations and to establish procedures, not inconsistent with the provisions of this subchapter, which are necessary or appropriate to carry out such provisions, and shall adopt reasonable and proper rules and regulations to regulate and provide for the nature and extent of the proofs and evidence and the method of taking and furnishing the same in order to establish the right to benefits hereunder."],[0,"(b) Administrative determination of entitlement to benefits; findings of fact; hearings; investigations; evidentiary hearings in reconsiderations of disability benefit terminations; subsequent applications"],[0,"(1) The Commissioner of Social Security is directed to make findings of fact, and decisions as to the rights of any individual applying for a payment under this subchapter. Any such decision by the Commissioner of Social Security which involves a determination of disability and which is in whole or in part unfavorable to such individual shall contain a statement of the case, in understandable language, setting forth a discussion of the evidence, and stating the Commissioner's determination and the reason or reasons upon which it is based. Upon request by any such individual or upon request by a wife, divorced wife, widow, surviving divorced wife, surviving divorced mother, surviving divorced father, husband, divorced husband, widower, surviving divorced husband, child, or parent who makes a showing in writing that his or her rights may be prejudiced by any decision the Commissioner of Social Security has rendered, the Commissioner shall give such applicant and such other individual reasonable notice and opportunity for a hearing with respect to such decision, and, if a hearing is held, shall, on the basis of evidence adduced at the hearing, affirm, modify, or reverse the Commissioner's findings of fact and such decision. Any such request with respect to such a decision must be filed within sixty days after notice of such decision is received by the individual making such request. The Commissioner of Social Security is further authorized, on the Commissioner's own motion, to hold such hearings and to conduct such investigations and other proceedings as the Commissioner may deem necessary or proper for the administration of this subchapter. In the course of any hearing, investigation, or other proceeding, the Commissioner may administer oaths and affirmations, examine witnesses, and receive evidence. Evidence may be received at any hearing before the Commissioner of Social Security even though inadmissible under rules of evidence applicable to court procedure."],[0,"(2) In any case where—"],[1,"(A) an individual is a recipient of disability insurance benefits, or of child's, widow's, or widower's insurance benefits based on disability,"],[1,"(B) the physical or mental impairment on the basis of which such benefits are payable is found to have ceased, not to have existed, or to no longer be disabling, and"],[1,"(C) as a consequence of the finding described in subparagraph (B), such individual is determined by the Commissioner of Social Security not to be entitled to such benefits,"],[0,"any reconsideration of the finding described in subparagraph (B), in connection with a reconsideration by the Commissioner of Social Security (before any hearing under paragraph (1) on the issue of such entitlement) of the Commissioner's determination described in subparagraph (C), shall be made only after opportunity for an evidentiary hearing, with regard to the finding described in subparagraph (B), which is reasonably accessible to such individual. Any reconsideration of a finding described in subparagraph (B) may be made either by the State agency or the Commissioner of Social Security where the finding was originally made by the State agency, and shall be made by the Commissioner of Social Security where the finding was originally made by the Commissioner of Social Security. In the case of a reconsideration by a State agency of a finding described in subparagraph (B) which was originally made by such State agency, the evidentiary hearing shall be held by an adjudicatory unit of the State agency other than the unit that made the finding described in subparagraph (B). In the case of a reconsideration by the Commissioner of Social Security of a finding described in subparagraph (B) which was originally made by the Commissioner of Social Security, the evidentiary hearing shall be held by a person other than the person or persons who made the finding described in subparagraph (B)."],[0,"(3)(A) A failure to timely request review of an initial adverse determination with respect to an application for any benefit under this subchapter or an adverse determination on reconsideration of such an initial determination shall not serve as a basis for denial of a subsequent application for any benefit under this subchapter if the applicant demonstrates that the applicant, or any other individual referred to in paragraph (1), failed to so request such a review acting in good faith reliance upon incorrect, incomplete, or misleading information, relating to the consequences of reapplying for benefits in lieu of seeking review of an adverse determination, provided by any officer or employee of the Social Security Administration or any State agency acting under section 421 of this title."],[0,"(B) In any notice of an adverse determination with respect to which a review may be requested under paragraph (1), the Commissioner of Social Security shall describe in clear and specific language the effect on possible entitlement to benefits under this subchapter of choosing to reapply in lieu of requesting review of the determination."],[0,"(c) Wage records"],[0,"(1) For the purposes of this subsection—"],[1,"(A) The term \"year\" means a calendar year when used with respect to wages and a taxable year when used with respect to self-employment income."],[1,"(B) The term \"time limitation\" means a period of three years, three months, and fifteen days."],[1,"(C) The term \"survivor\" means an individual's spouse, surviving divorced wife, surviving divorced husband, surviving divorced mother, surviving divorced father, child, or parent, who survives such individual."],[1,"(D) The term \"period\" when used with respect to self-employment income means a taxable year and when used with respect to wages means—"],[2,"(i) a quarter if wages were reported or should have been reported on a quarterly basis on tax returns filed with the Secretary of the Treasury or his delegate under section 6011 of the Internal Revenue Code of 1986 or regulations thereunder (or on reports filed by a State under section 418(e) 1 of this title (as in effect prior to December 31, 1986) or regulations thereunder),"],[2,"(ii) a year if wages were reported or should have been reported on a yearly basis on such tax returns or reports, or"],[2,"(iii) the half year beginning January 1 or July 1 in the case of wages which were reported or should have been reported for calendar year 1937."],[0,"(2)(A) On the basis of information obtained by or submitted to the Commissioner of Social Security, and after such verification thereof as the Commissioner deems necessary, the Commissioner of Social Security shall establish and maintain records of the amounts of wages paid to, and the amounts of self-employment income derived by, each individual and of the periods in which such wages were paid and such income was derived and, upon request, shall inform any individual or his survivor, or the legal representative of such individual or his estate, of the amounts of wages and self-employment income of such individual and the periods during which such wages were paid and such income was derived, as shown by such records at the time of such request."],[0,"(B)(i) In carrying out the Commissioner's duties under subparagraph (A) and subparagraph (F), the Commissioner of Social Security shall take affirmative measures to assure that social security account numbers will, to the maximum extent practicable, be assigned to all members of appropriate groups or categories of individuals by assigning such numbers (or ascertaining that such numbers have already been assigned):"],[1,"(I) to aliens at the time of their lawful admission to the United States either for permanent residence or under other authority of law permitting them to engage in employment in the United States and to other aliens at such time as their status is so changed as to make it lawful for them to engage in such employment;"],[1,"(II) to any individual who is an applicant for or recipient of benefits under any program financed in whole or in part from Federal funds including any child on whose behalf such benefits are claimed by another person; and"],[1,"(III) to any other individual when it appears that he could have been but was not assigned an account number under the provisions of subclauses (I) or (II) but only after such investigation as is necessary to establish to the satisfaction of the Commissioner of Social Security, the identity of such individual, the fact that an account number has not already been assigned to such individual, and the fact that such individual is a citizen or a noncitizen who is not, because of his alien status, prohibited from engaging in employment;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/405?type=usc&year=mostrecent&link-type=html"},"by":{"0":"40, 41, 42","1":"12, 20","2":"11, 12"},"q":[{"src":"brief","b":0,"text":"final decision[s] … made after a hearing","cite":"42 U.S.C. § 405(g)"},{"src":"brief","b":1,"text":"final decision * * * made after a hearing","cite":"42 U.S.C. 405(g)"},{"src":"brief","b":1,"text":"authorize[d] federal judicial review of ‘any final decision of the Secretary made after a hearing to which [the claimant] was a party.’","cite":"42 U.S.C. 405(g)"}]},{"t":"usc","label":"45 U.S.C. § 231a","url":"https://www.law.cornell.edu/uscode/text/45/231a","subs":["(a)(1)","(a)","(a)(1)(i)","(a)(1)(v)"],"stext":{"head":"§231a. Annuity eligibility requirements","paras":[[0,"(a) Individuals eligible for annuities; disability standards; proof of continued disability"],[0,"(1) The following-described individuals, if they shall have completed ten years of service (or, for purposes of paragraphs (i), (iii), and (v), five years of service, all of which accrues after December 31, 1995) and shall have filed application for annuities, shall, subject to the conditions set forth in subsections (e), (f), and (h), be entitled to annuities in the amounts provided under section 231b of this title—"],[1,"(i) individuals who have attained retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]);"],[1,"(ii) individuals who have attained the age of sixty and have completed thirty years of service;"],[1,"(iii) individuals who have attained the age of sixty-two and have completed less than thirty years of service, but the annuity of such individuals shall be reduced by 1/180 for each of the first 36 months that he or she is under retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]) when the annuity begins to accrue and by 1/240 for each additional month that he or she is under retirement age (as defined in section 216(l) of the Social Security Act) when the annuity begins to accrue;"],[1,"(iv) individuals who have a current connection with the railroad industry, whose permanent physical or mental condition is such as to be disabling for work in their regular occupation, and who (A) have completed twenty years of service or (B) have attained the age of sixty; and"],[1,"(v) individuals whose permanent physical or mental condition is such that they are unable to engage in any regular employment."],[0,"(2) For the purposes of paragraph (iv) of subdivision (1), the Board, with the cooperation of employers and employees, shall secure the establishment of standards determining the physical and mental conditions which permanently disqualify employees for work in the several occupations in the railroad industry, and the Board, employers, and employees shall cooperate in the promotion of the greatest practicable degree of uniformity in the standards applied by the several employers. An individual's condition shall be deemed to be disabling for work in his regular occupation if he will have been disqualified by his employer for service in his regular occupation in accordance with the applicable standards so established; if the employee will not have been so disqualified by his employer, the Board shall determine whether his condition is disabling for work in his regular occupation in accordance with the standards generally established; and, if the employee's regular occupation is not one with respect to which standards will have been established, the standards relating to a reasonably comparable occupation shall be used. If there is no such comparable occupation, the Board shall determine whether the employee's condition is disabling for work in his regular occupation by determining whether under the practices generally prevailing in industries in which such occupation exists such condition is a permanent disqualification for work in such occupation. For purposes of this subdivision and paragraph (iv) of subdivision (1), an employee's \"regular occupation\" shall be deemed to be the occupation in which he will have been engaged in more calendar months than the calendar months in which he will have been engaged in any other occupation during the last preceding five calendar years, whether or not consecutive, in each of which years he will have earned wages or salary, except that, if an employee establishes that during the last fifteen consecutive calendar years he will have been engaged in another occupation in one-half or more of all the months in which he will have earned wages or salary, he may claim such other occupation as his regular occupation."],[0,"(3) Such satisfactory proof shall be made from time to time as prescribed by the Board, of the disability provided for in paragraph (iv) or (v) of subdivision (1) and of the continuance of such disability (according to the standards applied in the establishment of such disability) until the employee attains retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]). If the individual fails to comply with the requirements prescribed by the Board as to proof of the continuance of the disability until he attains retirement age (as defined in section 216(l) of the Social Security Act), his right to an annuity by reason of such disability shall, except for good cause shown to the Board, cease, but without prejudice to his rights to any subsequent annuity to which he may be entitled."],[0,"(4) An individual who is entitled to an annuity under paragraph (v) of subdivision (1), but who does not have at least ten years of service, shall, prior to the month in which the individual attains age 62, be entitled only to an annuity amount computed under section 231b(a) of this title (without regard to section 231b(a)(2) of this title) or section 231b(f)(3) of this title. Upon attainment of age 62, such an individual may also be entitled to an annuity amount computed under section 231b(b) of this title, but such annuity amount shall be reduced for early retirement in the same manner as if the individual were entitled to an annuity under subsection (a)(1)(iii)."],[0,"(b) Individuals eligible for supplemental annuities"],[0,"An individual who—"],[1,"(i) has attained age 60 and completed thirty years of service or attained age 65;"],[1,"(ii) has completed twenty-five years of service;"],[1,"(iii) is entitled to the payment of an annuity under subsection (a)(1);"],[1,"(iv) had a current connection with the railroad industry at the time such annuity began to accrue; and"],[1,"(v) has performed compensated service in at least one month prior to October 1, 1981;"],[0,"shall, subject to the conditions set forth in subsections (e) and (h), be entitled to a supplemental annuity in the amount provided under section 231b of this title: Provided, however, That in cases where an individual's annuity under subsection (a)(1) begins to accrue on other than the first day of the month, the amount of any supplemental annuity to which he is entitled for that month shall be reduced by one-thirtieth for each day with respect to which he is not entitled to an annuity under subsection (a)(1)."],[0,"(c) Spouses eligible for annuities"],[0,"(1) The spouse of an individual, if—"],[1,"(i) such individual (A) is entitled to an annuity under subsection (a)(1) and (B) has attained the age of 60 and has completed thirty years of service or has attained the age of 62, and"],[1,"(ii) such spouse (A) has attained retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]), or (B) has attained the age of 60 and such individual has completed thirty years of service, or (C), in the case of a wife, has in her care (individually or jointly with her husband) a child who meets the qualifications prescribed in paragraph (iii) of subsection (d)(1) (without regard to the provisions of clause (B) of such paragraph),"],[0,"shall, subject to the conditions set forth in subsections (e), (f), and (h), be entitled to a spouse's annuity, if he or she has filed application therefor, in the amount provided under section 231c of this title."],[0,"(2) A spouse who would be entitled to an annuity under subdivision (1) or a divorced wife who would be entitled to an annuity under subdivision (4) if he or she had attained retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]) may elect upon or after attaining the age of 62 to receive such annuity, but the annuity in any such case shall be reduced by 1/144 for each of the first 36 months that the spouse or divorced wife is under retirement age (as defined in section 216(l) of the Social Security Act) when the annuity begins to accrue and by 1/240 for each additional month that the spouse or divorced wife is under retirement age (as defined in section 216(l) of the Social Security Act) when the annuity begins to accrue, except that the annuity of a divorced wife who was previously entitled to a spouse annuity which was reduced under this subdivision shall be reduced by the same percentage as was applicable to the spouse annuity."],[0,"(3) For the purposes of this subchapter, the term \"spouse\" shall mean the wife or husband of an annuitant under subsection (a)(1) who (i) was married to such annuitant for a period of not less than one year immediately preceding the day on which the application for a spouse's annuity is filed, or in the month prior to his or her marriage to such annuitant was eligible for an annuity under paragraph (i) or (iv) of subsection (d)(1) or, on the basis of disability, under paragraph (iii) thereof, or is the parent of such annuitant's son or daughter; and (ii) in the case of a husband, was receiving at least one-half of his support from his wife at the time his wife's annuity under subsection (a)(1) began."],[0,"(4) The \"divorced wife\" (as defined in section 216(d) of the Social Security Act [42 U.S.C. 416(d)]) of an individual, if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/231a?type=usc&year=mostrecent&link-type=html"},"by":{"0":"7","1":"3, 4, 3, 3, 3"},"q":[{"src":"brief","b":0,"text":"permanent physical or mental condition is such that [he is] unable to engage in any regular employment.","cite":"45 U.S.C. § 231a(a)(1)(v)"},{"src":"brief","b":1,"text":"whose permanent physical or mental condition is such that they are unable to engage in any regular employment.","cite":"45 U.S.C. 231a(a)(1)(v)"}]},{"t":"law","label":"Pub. L. No. 93-455","url":"https://www.govinfo.gov/link/statute/88/1305","by":{"0":"5"}},{"t":"case","label":"Block v. Community Nutrition Inst.","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"by":{"1":"42"},"q":[{"src":"brief","b":1,"text":"the Court has found the standard met, and the presumption favoring judicial review overcome, whenever the congressional intent to preclude judicial review is fairly discernible in the statutory scheme.","cite":"467 U.S. 340, 351"}]},{"t":"case","label":"Chevron U.S.A. Inc. v. Natural Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"reading * * * frankly seems to us the more natural,","cite":"467 U.S. 837, 842"}]},{"t":"case","label":"Dada v. Mukasey","cite":"554 U.S. 1","y":2008,"id":"2007/06-1181","sc":1,"by":{"1":"37"}},{"t":"case","label":"Department of Homeland Sec. v. MacLean","cite":"574 U.S. 383","y":2015,"id":"2014/13-894","sc":1,"by":{"1":"28"},"q":[{"src":"brief","b":1,"text":"Congress ‘uses particular language in one section of a statute but omits it in another,’ this Court presumes that choice was deliberate,","cite":"574 U.S. 383, 391"}]},{"t":"case","label":"Elgin v. Department of Treasury","cite":"567 U.S. 1","y":2012,"id":"2011/11-45","sc":1,"by":{"1":"46"},"q":[{"src":"brief","b":1,"text":"Congress intends to preclude judicial review of constitutional claims","cite":"567 U.S. 1, 9"}]},{"t":"case","label":"Federal Mar. Comm’n v. Seatrain Lines, Inc.","cite":"411 U.S. 726","y":1973,"id":"1972/71-1647","sc":1,"by":{"1":"26"}},{"t":"case","label":"ICC v. Brotherhood of Locomotive Eng’rs","cite":"482 U.S. 270","y":1987,"id":"1986/85-792","sc":1,"by":{"1":"36, 42","2":"8, 21"},"q":[{"src":"brief","b":1,"text":"especially in light of the traditional rule of administrative law that an agency’s refusal to reopen a closed case is generally ‘committed to agency discretion by law’ and therefore exempt from judicial review.","cite":"482 U.S. 270, 282"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"impossibility of devising an adequate standard of review","cite":"482 U. S. 270, 282"},{"src":"argument","who":"Ms. Harris","text":"So, in Brotherhood of Locomotive Engineers, for instance, the Court distinguished between those two things and said it would be fundamentally unfair to deny someone the opportunity to present new evidence that the agency hadn't considered before."},{"src":"argument","who":"Ms. Harris","text":"And I think that's why Brotherhood of Locomotive Engineers actually used the rehearing en banc hypothetical to distinguish and illustrate the distinction between new evidence, reopening-type claims, which are judicially reviewable, and rehashing claims, which are generally committed to agency discretion."},{"src":"argument","who":"Ms. Harris","text":"Because, if you thought of it that way, I think you'd have to override a really long tradition of judicial review in cases like Kucana versus Holder and Brotherhood of Locomotive Engineers that holds the contrary and says denials of reopening that are based on new evidence are judicially reviewable because they're final agency actions."}]},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"575 U.S. 480","y":2015,"id":"2014/13-1019","sc":1,"by":{"1":"41, 43"}},{"t":"case","label":"Paroline v. United States","cite":"572 U.S. 434","y":2014,"id":"2013/12-8561","sc":1,"by":{"1":"18, 25, 26, 27","2":"14, 15"},"q":[{"src":"brief","b":1,"text":"[w]hen several words are followed by a clause which is applicable as much to the first and other words as to the last, the natural construction of the language demands that the clause be read as applicable to all.","cite":"572 U.S. at 447"}]},{"t":"case","label":"Porto Rico Ry., Light & Power Co. v. Mor","cite":"253 U.S. 345","y":1920,"id":"scdb/1919-067","sc":1,"by":{"1":"26"}},{"t":"case","label":"Rimini St., Inc. v. Oracle USA, Inc.","cite":"139 S. Ct. 873","y":2019,"id":"2018/17-1625","sc":1,"by":{"1":"27"}},{"t":"case","label":"SEC v. Louisiana Pub. Serv. Comm’n","cite":"353 U.S. 368","y":1957,"id":"1956/466","sc":1,"by":{"1":"32","2":"5"}},{"t":"case","label":"Sones v. United States R.R. Ret. Bd.","cite":"933 F.2d 636","y":1991,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/933/636/","by":{"1":"48"}},{"t":"case","label":"Taylor v. United States","cite":"136 S. Ct. 2074","y":2016,"id":"2015/14-6166","sc":1,"by":{"1":"18","2":"15"}},{"t":"case","label":"Thryv, Inc. v. Click-to-Call Techs., LP","cite":"140 S. Ct. 1367","y":2020,"id":"2019/18-916","sc":1,"by":{"1":"47"},"q":[{"src":"brief","b":1,"text":"not decide whether mandamus would be available in an extraordinary case.","cite":"140 S. Ct. 1367, 1374 n.6"}]},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"by":{"1":"26"}},{"t":"case","label":"United States v. Standard Brewery, Inc.","cite":"251 U.S. 210","y":1920,"id":"scdb/1919-173","sc":1,"by":{"1":"26","2":"15"},"q":[{"src":"brief","b":2,"text":"in situations … akin to mere fortuity.","cite":"251 U.S. 210"}]},{"t":"case","label":"United States v. United Verde Copper Co.","cite":"196 U.S. 207","y":1905,"id":"scdb/1904-162","sc":1,"by":{"1":"26"}},{"t":"case","label":"United States Army Corps of Eng’rs v. Hawkes Co.","cite":"136 S. Ct. 1807","y":2016,"id":"2015/15-290","sc":1,"by":{"1":"33, 38"}},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"by":{"1":"46"}},{"t":"case","label":"Your Home Visiting Nurse Servs., Inc. v. Shalala","cite":"525 U.S. 449","y":1999,"id":"1998/97-1489","sc":1,"by":{"1":"passim","2":"4, 5, 8, 20"},"q":[{"src":"brief","b":1,"text":"refusal to make a new determination.","cite":"525 U.S. 449, 453"},{"src":"brief","b":1,"text":"[t]he right of a [claimant] to seek reopening exists only by grace of the [agency].","cite":"525 U.S. at 454"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"the refusal to make a new determination.","cite":"525 U. S. 449, 453"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"frustrate the statutory purpose of imposing a [time] limit on judicial review.","cite":"525 U. S., at 454"},{"src":"argument","who":"Justice Breyer","text":"It's both Your Home Visiting Nurse and also Califano v. Sanders. Then you have the fact that nobody -- no lower court decided in your favor, I think -- maybe there was an exception, I don't know -- since the 1960s or 1970s, and since then, the cases have gone the other way in the lower courts, and it would make a kind of hash of the statute of limitations."},{"src":"argument","who":"Ms. Harris","text":"I'd like to take Your Home and Califano first, because I think that Your Home, when it said that there is a sort of -- that reopening seemed like a refusal --"},{"src":"argument","who":"Ms. Harris","text":"-- to make another decision, Your Home, again, is sort of talking about the situation where there's a rehash claim. And if you took Your Home to be foreclosing judicial review of all sorts of reopening claims based on new evidence, that would be a sea change in the way the Court has considered them."}]},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)(2)"],"stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"by":{"1":"33","2":"8, 20"},"q":[{"src":"brief","b":2,"text":"agency action … committed to agency discretion by law,","cite":"5 U.S.C. § 701(a)(2)"},{"src":"brief","b":2,"text":"committed to agency discretion by law","cite":"5 U.S.C. § 701(a)(2)"}]},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","by":{"1":"33"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"1":"38"}},{"t":"usc","label":"45 U.S.C. § 228k","url":"https://www.law.cornell.edu/uscode/text/45/228k","subs":["(1940)"],"by":{"1":"47, 48"},"q":[{"src":"brief","b":1,"text":"to take action or to make a decision.","cite":"45 U.S.C. 228k"}]},{"t":"usc","label":"45 U.S.C. § 231","url":"https://www.law.cornell.edu/uscode/text/45/231","by":{"1":"2"}},{"t":"usc","label":"45 U.S.C. § 231f","url":"https://www.law.cornell.edu/uscode/text/45/231f","subs":["(a)","(b)(3)","(b)(5)","(b)(1)"],"by":{"1":"3, 4, 3, 4, 45","2":"19"},"q":[{"src":"brief","b":1,"text":"any person aggrieved by a decision on his application for an annuity or other benefit.","cite":"45 U.S.C. 231f(b)(3)"},{"src":"brief","b":1,"text":"establish and promulgate rules and regulations to provide for the adjustment of all controversial matters arising in the administration of [the RRA].","cite":"45 U.S.C. 231f(b)(5)"}]},{"t":"usc","label":"45 U.S.C. § 231g","url":"https://www.law.cornell.edu/uscode/text/45/231g","stext":{"head":"§231g. Court jurisdiction","paras":[[0,"Decisions of the Board determining the rights or liabilities of any person under this subchapter shall be subject to judicial review in the same manner, subject to the same limitations, and all provisions of law shall apply in the same manner as though the decision were a determination of corresponding rights or liabilities under the Railroad Unemployment Insurance Act [45 U.S.C. 351 et seq.] except that the time within which proceedings for the review of a decision with respect to an annuity, supplemental annuity, or lump-sum benefit may be commenced shall be one year after the decision will have been entered upon the records of the Board and communicated to the claimant."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/231g?type=usc&year=mostrecent&link-type=html"},"by":{"1":"45"},"q":[{"src":"brief","b":1,"text":"determining the rights or liabilities of any person under [the RRA] shall be subject to judicial review in the same manner, subject to the same limitations, and all provisions of law shall apply in the same manner as though the decision were a determination of corresponding rights or liabilities under the","cite":"45 U.S.C. 231g"},{"src":"brief","b":1,"text":"rights or liabilities * * * under [the RRA].","cite":"45 U.S.C. 231g"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"shall be subject to judicial review in the same manner, subject to the same limitations, and all provisions of law shall apply in the same manner as though the decision were a determination of corresponding rights or liabilities under the Railroad Unemployment Insurance Act.","cite":"45 U. S. C. §231g"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"determining the rights or liabilities of any person.","cite":"45 U. S. C. §231g"},{"src":"argument","who":"Ms. Harris","text":"Any final decision tracks the broad language of Section 231g, the RRA's parallel judicial review provisions governing claims like Mr. Salinas's."},{"src":"argument","who":"Justice Alito","text":"This is a case under the former. Is there any reason why we can't decide it simply by looking at the language of that provision, Section 231g?"},{"src":"argument","who":"Mr. Raynor","text":"I agree with you that the determination of rights or liabilities language in Section 231g is a gating mechanism. And if you didn't think that a reopening denial qualified as a determination of rights or liabilities, which, in our view, would be correct under Your Home, then judicial review would not be available under the RRA."}]},{"t":"usc","label":"45 U.S.C. § 231h","url":"https://www.law.cornell.edu/uscode/text/45/231h","by":{"1":"45"},"q":[{"src":"brief","b":1,"text":"long before the employee seeks benefits.","cite":"45 U.S.C. 231h"}]},{"t":"usc","label":"45 U.S.C. § 351","url":"https://www.law.cornell.edu/uscode/text/45/351","subs":["(n)"],"by":{"1":"3, 5"}},{"t":"usc","label":"45 U.S.C. § 352","url":"https://www.law.cornell.edu/uscode/text/45/352","subs":["(2020)","(c)(1)(A)"],"by":{"1":"3, 3"}},{"t":"usc","label":"45 U.S.C. § 355","url":"https://www.law.cornell.edu/uscode/text/45/355","subs":["(b)","(c)","(c)(1)","(c)(2)","(c)(3)","(c)(4)","(c)(5)","(d)","(g)"],"stext":{"head":"§355. Claims for benefits","paras":[[0,"(a) Publication of Board's regulations"],[0,"Claims for benefits and appeals from determinations with respect thereto shall be made in accordance with such regulations as the Board shall prescribe. Each employer shall post and maintain, in places readily accessible to employees in his service, such printed statements concerning such regulations as the Board supplies to him for such purpose, and shall keep available to his employees copies of such printed statements. Such printed statements shall be supplied by the Board to each employer without cost to him."],[0,"(b) Findings, hearings, investigations, etc., by Board"],[0,"The Board is authorized and directed to make findings of fact with respect to any claim for benefits and to make decisions as to the right of any claimant to benefits. The Board is further authorized to hold such hearings, to conduct such investigations and other proceedings, and to establish, by regulations or otherwise, such procedures as it may deem necessary or proper for the determination of a right to benefits. When a claim for benefits is filed with the Board, the Board shall provide notice of such claim to the claimant's base-year employer or employers and afford such employer or employers an opportunity to submit information relevant to the claim before making an initial determination on the claim. When the Board initially determines to pay benefits to a claimant under this chapter, the Board shall provide notice of such determination to the claimant's base-year employer or employers."],[0,"(c) Hearing and review of decisions on claims"],[0,"(1) Each qualified employee whose claim for benefits has been denied in whole or in part upon an initial determination with respect thereto upon a basis other than one which is reviewable pursuant to one of the succeeding paragraphs of this subsection, shall be granted an opportunity for a fair hearing thereon before a referee or such other reviewing body as the Board may establish or assign thereto. In any such case the Board or the person or reviewing body so established or assigned shall, by publication or otherwise, notify all parties properly interested of their right to participate in the hearing and of the time and place of the hearing."],[0,"(2) Any claimant whose claim for benefits has been denied in an initial determination with respect thereto upon the basis of his not being a qualified employee, and any claimant who contends that under an initial determination of his claim he has been awarded benefits at less than the proper rate, may appeal to the Board for the review of such determination. Thereupon the Board shall review the determination and for such review may designate one of its officers or employees to receive evidence and to report to the Board thereon together with recommendations. In any such case the Board or the person so designated shall, by publication or otherwise, notify all parties properly interested of their right to participate in the proceeding and, if a hearing is to be held, of the time and place of the hearing. At the request of any party properly interested the Board shall provide for a hearing, and may provide for a hearing on its own motion. The Board shall prescribe regulations governing the appeals provided for in this paragraph and for decisions upon such appeal."],[0,"(3) Any base-year employer of a claimant whose claim for benefits has been granted in whole or in part, either in an initial determination with respect thereto or in a determination after a hearing pursuant to paragraph (1), and who contends that the determination is erroneous for a reason or reasons other than a reason that is reviewable under paragraph (4), may appeal to the Board for review of such determination. Despite such an appeal, the benefits awarded shall be paid to such claimant, subject to recovery by the Board if and to the extent found on the appeal to have been erroneously awarded. The Board shall take such action as is appropriate to recover the amount of such benefits including if feasible adjustment in subsequent payments pursuant to the first two paragraphs of section 352(d) of this title. Upon an appeal, the Board shall review the determination appealed from and for such review may designate one of its officers or employees to receive evidence and report to the Board thereof together with recommendations. In any such case the Board or the person so designated shall, by publication or otherwise, notify all parties properly interested of their right to participate in the proceeding and, if a hearing is to be held, of the time and place of the hearing. At the request of any party properly interested the Board shall provide for a hearing, and may provide for a hearing on its own motion. The Board shall prescribe regulations governing the appeals provided for in this paragraph and for decisions upon such appeal."],[0,"(4) In any case in which benefits are awarded to a claimant in whole or in part upon the basis of pay earned in the service of a person or company found by the Board to be an employer as defined in this chapter but which denies that it is such an employer, such benefits awarded on such basis shall be paid to such claimant subject to a right of recovery of such benefits. The Board shall thereupon designate one of its officers or employees to receive evidence and to report to the Board on whether such benefits should be repaid. The Board may also designate one of its officers or employees to receive evidence and report to the Board whether or not any person or company is entitled to a refund of contributions or should be required to pay contributions under this chapter, regardless of whether or not any claims for benefits will have been filed upon the basis of service in the employ of such person or company, and shall follow such procedure if contributions are assessed and payment is refused or payment is made and a refund claimed upon the basis that such person or company is or will not have been liable for such contributions. In any such case the Board or the person so designated shall, by publication or otherwise, notify all parties properly interested of their right to participate in the proceeding and, if a hearing is to be held, of the time and place of the hearing. At the request of any party properly interested the Board shall provide for a hearing, and may provide for a hearing on its own motion. The Board shall prescribe regulations governing the proceedings provided for in this paragraph and for decisions upon such proceedings."],[0,"(5) Final decision of the Board in the cases provided for in the preceding three paragraphs shall be communicated to the claimant and to the other interested parties within fifteen days after it is made. Any properly interested party notified, as hereinabove provided, of his right to participate in the proceedings may obtain a review of any such decision by which he claims to be aggrieved or the determination of any issue therein in the manner provided in subsection (f) of this section with respect to the review of the Board's decisions upon claims for benefits and subject to all provisions of law applicable to the review of such decisions. Subject only to such review, the decision of the Board upon all issues determined in such decision shall be final and conclusive for all purposes and shall conclusively establish all rights and obligations, arising under this chapter, of every party notified as hereinabove provided of his right to participate in the proceedings."],[0,"(6) For purposes of this subsection and subsections (d) and (f), any base-year employer of the claimant is a properly interested party."],[0,"(7) Any issue determinable pursuant to this subsection and subsection (f) of this section shall not be determined in any manner other than pursuant to this subsection and subsection (f)."],[0,"(d) Decisions of reviewing bodies; review and finality"],[0,"The Board shall prescribe regulations governing the filing of cases with and the decision of cases by reviewing bodies, and the review of such decisions. The Board may provide for intermediate reviews of such decisions by such bodies as the Board may establish or assign thereto. The Board may (i) on its own motion review a decision of an intermediate reviewing body on the basis of the evidence previously submitted in such case, and may direct the taking of additional evidence, or (ii) permit such parties as it finds properly interested in the proceedings to take appeals to the Board. Unless a review or an appeal is had pursuant to this subsection, the decision of an intermediate reviewing body shall, subject to such regulations as the Board may prescribe, be deemed to be the final decision of the Board."],[0,"(e) Application of rules of evidence in law and equity; notice of findings"],[0,"In any proceeding other than a court proceeding, the rules of evidence prevailing in courts of law or equity shall not be controlling, but a full and complete record shall be kept of all proceedings and testimony, and the Board's final determination, together with its findings of fact and conclusions of law in connection therewith, shall be communicated to the parties within fifteen days after the date of such final determination."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/355?type=usc&year=mostrecent&link-type=html"},"by":{"1":"6, 6, 21, 30, 44, 21, 30, 44, 21, 30, 44, 21, 21, 5, 5, 5, 5, 5, 5","2":"passim"},"q":[{"src":"brief","b":1,"text":"[a]ny properly interested party notified * * * of his right to participate in the proceedings may obtain a review of any such decision by which he claims to be aggrieved or the determination of any issue therein in the manner provided in subsection (f ).","cite":"45 U.S.C. 355(c)"},{"src":"brief","b":1,"text":"any other party aggrieved by a final decision under subsection (c) of this section.","cite":"45 U.S.C. 355"},{"src":"brief","b":2,"text":"obtain a review of any final decision of the Board.","cite":"45 U.S.C. § 355(f)"},{"src":"brief","b":2,"text":"Any claimant, or any railway labor organization …, or any base-year employer …, or any other party aggrieved by a final decision under [section 355(c)] … may … obtain a review of any final decision of the Board.","cite":"45 U.S.C. § 355(f)"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"any other party aggrieved by a final decision under subsection (c) of this section.","cite":"45 U. S. C. §355"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"[f]inal decision[s] of the Board in the cases provided for in the preceding three paragraphs","cite":"45 U. S. C. §355(c)(5)"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"any such decision by which he claims to be aggrieved.","cite":"45 U. S. C. §355(c)(5)"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"pursuant to this subsection and subsection (f ).","cite":"45 U. S. C. §355(c)(7)"},{"src":"argument","who":"Mr. Raynor","text":"So even if you wanted to go just on the basis of a plain meaning approach to determinations of rights or liabilities, that would allow conformity between 231g and Section 355."}]},{"t":"usc","label":"45 U.S.C. § 358","url":"https://www.law.cornell.edu/uscode/text/45/358","by":{"1":"5"}},{"t":"usc","label":"45 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/45/151","by":{"1":"17"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","by":{"1":"31"}},{"t":"usc","label":"42 U.S.C. § 1395oo","url":"https://www.law.cornell.edu/uscode/text/42/1395oo","subs":["(a)(1)(A)(i)"],"stext":{"head":"§1395oo. Provider Reimbursement Review Board","paras":[[0,"(a) Establishment"],[0,"Any provider of services which has filed a required cost report within the time specified in regulations may obtain a hearing with respect to such cost report by a Provider Reimbursement Review Board (hereinafter referred to as the \"Board\") which shall be established by the Secretary in accordance with subsection (h) and (except as provided in subsection (g)(2)) any hospital which receives payments in amounts computed under subsection (b) or (d) of section 1395ww of this title and which has submitted such reports within such time as the Secretary may require in order to make payment under such section may obtain a hearing with respect to such payment by the Board, if—"],[1,"(1) such provider—"],[2,"(A)(i) is dissatisfied with a final determination of the organization serving as its fiscal intermediary pursuant to section 1395h of this title as to the amount of total program reimbursement due the provider for the items and services furnished to individuals for which payment may be made under this subchapter for the period covered by such report, or"],[2,"(ii) is dissatisfied with a final determination of the Secretary as to the amount of the payment under subsection (b) or (d) of section 1395ww of this title,"],[2,"(B) has not received such final determination from such intermediary on a timely basis after filing such report, where such report complied with the rules and regulations of the Secretary relating to such report, or"],[2,"(C) has not received such final determination on a timely basis after filing a supplementary cost report, where such cost report did not so comply and such supplementary cost report did so comply,"],[1,"(2) the amount in controversy is $10,000 or more, and"],[1,"(3) such provider files a request for a hearing within 180 days after notice of the intermediary's final determination under paragraph (1)(A)(i), or with respect to appeals under paragraph (1)(A)(ii), 180 days after notice of the Secretary's final determination, or with respect to appeals pursuant to paragraph (1) (B) or (C), within 180 days after notice of such determination would have been received if such determination had been made on a timely basis."],[0,"(b) Appeals by groups"],[0,"The provisions of subsection (a) shall apply to any group of providers of services if each provider of services in such group would, upon the filing of an appeal (but without regard to the $10,000 limitation), be entitled to such a hearing, but only if the matters in controversy involve a common question of fact or interpretation of law or regulations and the amount in controversy is, in the aggregate, $50,000 or more."],[0,"(c) Right to counsel; rules of evidence"],[0,"At such hearing, the provider of services shall have the right to be represented by counsel, to introduce evidence, and to examine and cross-examine witnesses. Evidence may be received at any such hearing even though inadmissible under rules of evidence applicable to court procedure."],[0,"(d) Decisions of Board"],[0,"A decision by the Board shall be based upon the record made at such hearing, which shall include the evidence considered by the intermediary and such other evidence as may be obtained or received by the Board, and shall be supported by substantial evidence when the record is viewed as a whole. The Board shall have the power to affirm, modify, or reverse a final determination of the fiscal intermediary with respect to a cost report and to make any other revisions on matters covered by such cost report (including revisions adverse to the provider of services) even though such matters were not considered by the intermediary in making such final determination."],[0,"(e) Rules and regulations"],[0,"The Board shall have full power and authority to make rules and establish procedures, not inconsistent with the provisions of this subchapter or regulations of the Secretary, which are necessary or appropriate to carry out the provisions of this section. In the course of any hearing the Board may administer oaths and affirmations. The provisions of subsections (d) and (e) of section 405 of this title with respect to subpenas shall apply to the Board to the same extent as they apply to the Secretary with respect to subchapter II."],[0,"(f) Finality of decision; judicial review; determinations of Board authority; jurisdiction; venue; interest on amount in controversy"],[0,"(1) A decision of the Board shall be final unless the Secretary, on his own motion, and within 60 days after the provider of services is notified of the Board's decision, reverses, affirms, or modifies the Board's decision. Providers shall have the right to obtain judicial review of any final decision of the Board, or of any reversal, affirmance, or modification by the Secretary, by a civil action commenced within 60 days of the date on which notice of any final decision by the Board or of any reversal, affirmance, or modification by the Secretary is received. Providers shall also have the right to obtain judicial review of any action of the fiscal intermediary which involves a question of law or regulations relevant to the matters in controversy whenever the Board determines (on its own motion or at the request of a provider of services as described in the following sentence) that it is without authority to decide the question, by a civil action commenced within sixty days of the date on which notification of such determination is received. If a provider of services may obtain a hearing under subsection (a) and has filed a request for such a hearing, such provider may file a request for a determination by the Board of its authority to decide the question of law or regulations relevant to the matters in controversy (accompanied by such documents and materials as the Board shall require for purposes of rendering such determination). The Board shall render such determination in writing within thirty days after the Board receives the request and such accompanying documents and materials, and the determination shall be considered a final decision and not subject to review by the Secretary. If the Board fails to render such determination within such period, the provider may bring a civil action (within sixty days of the end of such period) with respect to the matter in controversy contained in such request for a hearing. Such action shall be brought in the district court of the United States for the judicial district in which the provider is located (or, in an action brought jointly by several providers, the judicial district in which the greatest number of such providers are located) or in the District Court for the District of Columbia and shall be tried pursuant to the applicable provisions under chapter 7 of title 5 notwithstanding any other provisions in section 405 of this title. Any appeal to the Board or action for judicial review by providers which are under common ownership or control or which have obtained a hearing under subsection (b) must be brought by such providers as a group with respect to any matter involving an issue common to such providers."],[0,"(2) Where a provider seeks judicial review pursuant to paragraph (1), the amount in controversy shall be subject to annual interest beginning on the first day of the first month beginning after the 180-day period as determined pursuant to subsection (a)(3) and equal to the rate of interest on obligations issued for purchase by the Federal Hospital Insurance Trust Fund for the month in which the civil action authorized under paragraph (1) is commenced, to be awarded by the reviewing court in favor of the prevailing party."],[0,"(3) No interest awarded pursuant to paragraph (2) shall be deemed income or cost for the purposes of determining reimbursement due providers under this chapter."],[0,"(g) Certain findings not reviewable"],[0,"(1) The finding of a fiscal intermediary that no payment may be made under this subchapter for any expenses incurred for items or services furnished to an individual because such items or services are listed in section 1395y of this title shall not be reviewed by the Board, or by any court pursuant to an action brought under subsection (f)."],[0,"(2) The determinations and other decisions described in section 1395ww(d)(7) of this title shall not be reviewed by the Board or by any court pursuant to an action brought under subsection (f) or otherwise."],[0,"(h) Composition and compensation"],[0,"The Board shall be composed of five members appointed by the Secretary without regard to the provisions of title 5 governing appointments in the competitive services. Two of such members shall be representative of providers of services. All of the members of the Board shall be persons knowledgeable in the field of payment of providers of services, and at least one of them shall be a certified public accountant. Members of the Board shall be entitled to receive compensation at rates fixed by the Secretary, but not exceeding the rate specified (at the time the service involved is rendered by such members) for grade GS–18 in section 5332 of title 5. The term of office shall be three years, except that the Secretary shall appoint the initial members of the Board for shorter terms to the extent necessary to permit staggered terms of office."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395oo?type=usc&year=mostrecent&link-type=html"},"by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"a final determination * * * as to the amount of total program reimbursement due the provider.","cite":"42 U.S.C. 1395oo(a)(1)(A)(i)"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"‘final determination . . . as to the amount of total program reimbursement due.’","cite":"42 U. S. C. §1395oo(a)(1)(A)(i)"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"as to the amount of total program reimbursement due the provider.","cite":"42 U. S. C. §1395oo(a)(1)(A)(i)"}]},{"t":"usc","label":"18 U.S.C. § 2252","url":"https://www.law.cornell.edu/uscode/text/18/2252","subs":["(b)(2)"],"by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 2259","url":"https://www.law.cornell.edu/uscode/text/18/2259","subs":["(b)(3)(F)(2012)"],"by":{"1":"25, 26"},"q":[{"src":"brief","b":1,"text":"‘familiar canon of statutory construction that [catchall] clauses are to be read as bringing within a statute categories similar in type to those specifically enumerated.’","cite":"18 U.S.C. 2259(b)(3)(F)"}]},{"t":"usc","label":"31 U.S.C. § 3526","url":"https://www.law.cornell.edu/uscode/text/31/3526","by":{"1":"23"}},{"t":"usc","label":"31 U.S.C. § 3530","url":"https://www.law.cornell.edu/uscode/text/31/3530","by":{"1":"23"}},{"t":"case","label":"Berry v. Dep’t of Labor","cite":"832 F.3d 627","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/832/627/","by":{"2":"4"}},{"t":"case","label":"Cappadora v. Celebrezze","cite":"356 F.2d 1","y":1966,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/356/1/","by":{"2":"21"}},{"t":"case","label":"FTC v. Mandel Brothers, Inc.","cite":"359 U.S. 385","y":1959,"id":"1958/234","sc":1,"by":{"2":"13"},"q":[{"src":"brief","b":2,"text":"‘any offence’ committed on the high seas, which, if committed in the body of a country, would be punishable with death.","cite":"359 U.S. 385"}]},{"t":"case","label":"Jama v. Immigration & Customs Enf’t","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"by":{"2":"13"},"q":[{"src":"brief","b":2,"text":"are just as likely to be words of differentiation as they are to be words of connection.","cite":"543 U.S. 335, 343 n.3"}]},{"t":"case","label":"Lomax v. Ortiz-Marquez","cite":"140 S. Ct. 1721","y":2020,"id":"2019/18-8369","sc":1,"by":{"2":"11"},"q":[{"src":"brief","b":2,"text":"[T]his Court may not narrow a provision’s reach by inserting words Congress chose to omit.","cite":"140 S. Ct. 1721, 1725"}]},{"t":"case","label":"MacFarland v. Elverson","cite":"32 App. D.C. 81","y":1908,"url":"https://www.courtlistener.com/c/App.%20D.C./32/81/","by":{"2":"13"}},{"t":"case","label":"Mims v. Arrow Fin. Servs., LLC","cite":"565 U.S. 368","y":2012,"id":"2011/10-1195","sc":1,"by":{"2":"10"}},{"t":"case","label":"Mulloy v. United States","cite":"398 U.S. 410","y":1970,"id":"1969/655","sc":1,"by":{"2":"4"}},{"t":"case","label":"Romag Fasteners, Inc. v. Fossil, Inc.","cite":"140 S. Ct. 1492","y":2020,"id":"2019/18-1233","sc":1,"by":{"2":"11"},"q":[{"src":"brief","b":2,"text":"when Congress has (as here) included the term in question elsewhere in the very same statutory provision.","cite":"140 S. Ct. 1492, 1495"}]},{"t":"case","label":"Service v. Dulles","cite":"354 U.S. 363","y":1957,"id":"1956/407","sc":1,"by":{"2":"19"}},{"t":"case","label":"Thole v. U.S. Bank N.A.","cite":"140 S. Ct. 1615","y":2020,"id":"2019/17-1712","sc":1,"by":{"2":"3"}},{"t":"case","label":"United States v. Palmer","cite":"16 U.S. 610","y":1818,"id":"scdb/1818-038","sc":1,"by":{"2":"13"}},{"t":"case","label":"Vill. of Barrington v. Surface Transp. Bd.","cite":"758 F.3d 326","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/758/326/","by":{"2":"21"}},{"t":"case","label":"Virginia v. Browner","cite":"80 F.3d 869","y":1996,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/80/869/","by":{"2":"13"},"q":[{"src":"brief","b":2,"text":"would be a partial mutilation of this Act.","cite":"80 F.3d 869, 877"}]},{"t":"reg","label":"20 C.F.R. § 260.9","url":"https://www.ecfr.gov/current/title-20/section-260.9","subs":["(a)"],"by":{"2":"19"}},{"t":"usc","label":"15 U.S.C. § 79k","url":"https://www.law.cornell.edu/uscode/text/15/79k","subs":["(b)(1952)"],"by":{"2":"5"}},{"t":"usc","label":"18 U.S.C. § 1951","url":"https://www.law.cornell.edu/uscode/text/18/1951","subs":["(b)(3)"],"by":{"2":"15"},"q":[{"src":"brief","b":2,"text":"all other commerce over which the United States has jurisdiction.","cite":"18 U.S.C. § 1951(b)(3)"}]}]};